"""Apply the school-scope UI migration to the selected site checkout."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'tmp/pathways-release/dist'
def edit(name,old,new):
 p=SITE/name;t=p.read_text(encoding='utf-8');assert old in t,(name,old[:70]);p.write_text(t.replace(old,new),encoding='utf-8')

edit('modules/ui.mjs',"export const url=(view,values={})=>'#'+new URLSearchParams({view,...Object.fromEntries", "export const url=(view,values={})=>'#'+new URLSearchParams({view,scope:globalThis.atlasSchoolScope||'all',...Object.fromEntries")
edit('app.js',"const previous=parse(current)","globalThis.atlasSchoolScope=p.get('scope')||sessionStorage.getItem('atlas-school-scope')||'all';p.set('scope',globalThis.atlasSchoolScope);sessionStorage.setItem('atlas-school-scope',globalThis.atlasSchoolScope);document.body.dataset.scope=globalThis.atlasSchoolScope;\n document.querySelectorAll('[data-school-scope]').forEach(a=>{const sp=new URLSearchParams(p);sp.set('scope',a.dataset.schoolScope);for(const k of ['target','node','relation','claim','band','subject'])sp.delete(k);a.href='#'+sp;a.setAttribute('aria-current',String(a.dataset.schoolScope===globalThis.atlasSchoolScope));});\n const previous=parse(current)")
edit('app.js',"history.scrollRestoration='manual';", "history.scrollRestoration='manual';\n const schoolBar=document.createElement('nav');schoolBar.className='school-scope-bar';schoolBar.setAttribute('aria-label','학교급별 보기');schoolBar.innerHTML='<span>학교급별 보기</span>'+[['all','전체'],['e','초등'],['m','중등'],['h','고등']].map(([id,label])=>`<a data-school-scope=\"${id}\" href=\"#view=network&scope=${id}\">${label}</a>`).join('');main.before(schoolBar);")
edit('modules/network.mjs',"export async function networkPage(){", "export async function networkPage(p=new URLSearchParams()){")
edit('modules/network.mjs',"if(!model)model=buildNetwork(catalog,f,c);", "const scope=p.get('scope')||'all',allowed={e:['초등학교'],m:['중학교'],h:['고등학교']}[scope];\n model=buildNetwork({...catalog,standards:catalog.standards.filter(s=>!allowed||allowed.includes(s.level))},f,c);")
edit('modules/network.mjs',"const params={node:state.selected", "const params={scope:globalThis.atlasSchoolScope||'all',node:state.selected")
edit('modules/network.mjs',"const ns=codes?.size?model.nodes.filter(n=>codes.has(n.code)):model.nodes;", "const ns=codes?.size?model.nodes.filter(n=>codes.has(n.code)):model.nodes;if(!ns.length)return;")
edit('modules/network.mjs',"el.classList.toggle('is-muted',!selected", "el.style.display=visible?'':'none';el.setAttribute('aria-hidden',String(!visible));el.classList.toggle('is-muted',!selected")
edit('modules/network.mjs',"el.classList.toggle('is-muted',!visible||", "el.style.display=visible?'':'none';el.classList.toggle('is-muted',!visible||")
edit('modules/network.mjs',"<strong>435 <small>성취기준", "<strong>${model.nodes.length} <small>성취기준")
edit('modules/network.mjs',"435개의 성취기준을 하나의 연결망으로.", "선택한 학교급의 성취기준과 내부 연결을 하나의 연결망으로.")
edit('modules/network.mjs',"전체 망에서 해당 노드를 밝게 표시했습니다.", "선택 범위의 기준과 연결만 표시했습니다.")

edit('modules/concept-pathways.mjs',"const n=conceptNeighborhood(data,p.get('target')),goal=byCode.get(n.target);", "const showExternal=p.get('external')==='1';\n const members=c.member_codes.filter(id=>inScope(byCode.get(id),scope));\n const allowed=new Set(showExternal?data.nodes.map(n=>n.id):data.nodes.filter(n=>inScope(byCode.get(n.id),scope)).map(n=>n.id));\n data={...data,nodes:data.nodes.filter(n=>allowed.has(n.id)),relations:data.relations.filter(r=>allowed.has(r.from.slice(9))&&allowed.has(r.to.slice(9)))};\n const expansions=data.relations.filter(r=>r.type==='generalizes').length;\n Object.assign(c,{member_codes:members,members:members.length,relations:data.relations.length,expansions,hierarchy_status:expansions?'expansion_draft':'order_unreviewed'});\n if(!members.length)return heading('SCHOOL SCOPE',c.title,'선택 학교급에 직접 분류된 기준이 없습니다.')+`<a class=\"button\" href=\"${url('hierarchy',{scope})}\">개념군 목록으로</a>`;\n const wanted=p.get('target');\n if(wanted&&!allowed.has(wanted))return heading('SCHOOL SCOPE',c.title,'이전 목표가 선택한 학교급 범위 밖입니다. 목표를 다시 선택하세요.')+members.map(id=>`<a class=\"button\" href=\"${url('hierarchy',{concept:c.id,target:id,scope})}\">${esc(id+' '+byCode.get(id).title)}</a>`).join('');\n const n=conceptNeighborhood({...data,concept:{...c,member_codes:members}},wanted),goal=byCode.get(n.target);")
edit('modules/concept-pathways.mjs',"target:n.target,scope,mode,...changes", "target:n.target,scope,mode,external:showExternal?'1':'',...changes")
edit('modules/concept-pathways.mjs',"${scopeSelect(scope).replace('학교급','학교급 강조')}", "<label><input type=\"checkbox\" name=\"external\" value=\"1\" ${showExternal?'checked':''}>다른 학교급 연결 함께 보기</label>")
edit('modules/concept-pathways.mjs',"범위 밖 기준은 맥락으로 남겨 두며 학교급 강조를 바꿔도 목표를 숨기지 않습니다.", "선택 학교급 내부 관계를 표시합니다. 다른 학교급의 연결은 별도 선택으로 펼칠 수 있습니다.")

edit('modules/flows.mjs',"types,levels}","types,levels,inScope}")
edit('modules/flows.mjs',"const flows=await conceptFlows(),q=", "const original=await conceptFlows(),scope=p.get('scope')||'all',allowed=c=>inScope(standard(c),scope);\n const flows={...original,strands:original.strands.map(t=>({...t,stages:t.stages.map(s=>({...s,codes:s.codes.filter(allowed),primary_codes:s.primary_codes.filter(allowed),related:s.related.filter(r=>allowed(r.code))}))}))};\n const q=")
edit('modules/flows.mjs',"const params={mode:'flow'", "const params={scope,mode:'flow'")
edit('modules/flows.mjs',"const evidence=selected?await connections():null;", "const rawEvidence=selected?await connections():null;const evidence=rawEvidence?{...rawEvidence,relations:rawEvidence.relations.filter(r=>!r.from.startsWith('standard:')||!r.to.startsWith('standard:')||allowed(r.from.slice(9))&&allowed(r.to.slice(9)))}:null;")
edit('modules/flows.mjs',"const scope=p.get('edgeScope')||(p.get('flowNode')?'all':'cross-school')", "const scope=p.get('edgeScope')||'all'")

css=SITE/'design.css';css.write_text(css.read_text(encoding='utf-8')+'''\n.school-scope-bar{display:flex;align-items:center;gap:8px;max-width:1440px;margin:18px auto;padding:0 24px;flex-wrap:wrap}.school-scope-bar span{margin-right:12px;font-weight:600}.school-scope-bar a{padding:9px 22px;border:1px solid #bfd0d4;border-radius:8px;text-decoration:none}.school-scope-bar a[aria-current=true]{background:#214d5b;color:white;border-color:#214d5b}\nbody[data-scope=e] .flow-stage-1,body[data-scope=e] .flow-stage-2,body[data-scope=m] .flow-stage-0,body[data-scope=m] .flow-stage-2,body[data-scope=h] .flow-stage-0,body[data-scope=h] .flow-stage-1{display:none}\nbody:not([data-scope=all]) .flow-row-line,body:not([data-scope=all]) .flow-map-header{grid-template-columns:minmax(180px,.7fr) minmax(0,2fr)}\nbody[data-scope=e] .flow-map-header .school-1,body[data-scope=e] .flow-map-header .school-2,body[data-scope=m] .flow-map-header .school-0,body[data-scope=m] .flow-map-header .school-2,body[data-scope=h] .flow-map-header .school-0,body[data-scope=h] .flow-map-header .school-1{display:none}\n''',encoding='utf-8')
print('school scope migration applied')
